#!/usr/bin/env node
'use strict';

const fs = require('fs');

function usage() {
  process.stderr.write('Usage: node uniq.js [-c] [-d] [-u]\n');
}

const args = process.argv.slice(2);
let count = false;
let repeated = false;
let unique = false;

for (const arg of args) {
  if (arg === '-c') count = true;
  else if (arg === '-d') repeated = true;
  else if (arg === '-u') unique = true;
  else {
    usage();
    process.exit(2);
  }
}

if (repeated && unique) {
  process.stderr.write('uniq: printing all duplicated and unique lines is invalid\n');
  process.exit(2);
}

// Read all of stdin, split into lines (handles trailing newline correctly).
const input = fs.readFileSync(0, 'utf8');
if (input.length === 0) process.exit(0);

const lines = input.split('\n');
// If input ends with a newline, drop the final empty element.
if (lines[lines.length - 1] === '') lines.pop();

// Group adjacent equal lines.
const groups = []; // { line, count }
for (const line of lines) {
  const last = groups[groups.length - 1];
  if (last && last.line === line) last.count++;
  else groups.push({ line, count: 1 });
}

let out = '';
for (const { line, count: n } of groups) {
  if (repeated && n < 2) continue;
  if (unique && n !== 1) continue;
  out += count ? String(n).padStart(7) + ' ' + line + '\n' : line + '\n';
}

process.stdout.write(out);

