'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const CLI = path.join(__dirname, 'uniq.js');

function run(input, args = []) {
  const res = spawnSync(process.execPath, [CLI, ...args], {
    input,
    encoding: 'utf8',
  });
  return { stdout: res.stdout, stderr: res.stderr, status: res.status };
}

test('no flags collapses adjacent duplicates', () => {
  const input = 'a\nb\nb\na\n';
  assert.strictEqual(run(input).stdout, 'a\nb\na\n');
});

test('non-adjacent duplicates are preserved', () => {
  // "a" appears twice but not adjacently: real uniq keeps both.
  const input = 'a\nb\na\n';
  assert.strictEqual(run(input).stdout, 'a\nb\na\n');
});

test('-c prefixes counts', () => {
  const input = 'a\nb\nb\ncccc\ncccc\ncccc\n';
  assert.strictEqual(
    run(input, ['-c']).stdout,
    '      1 a\n      2 b\n      3 cccc\n'
  );
});

test('-c with non-adjacent repeats counts separately', () => {
  const input = 'x\nx\ny\nx\n';
  assert.strictEqual(
    run(input, ['-c']).stdout,
    '      2 x\n      1 y\n      1 x\n'
  );
});

test('-d prints only duplicated lines', () => {
  const input = 'a\na\nb\nc\nc\nd\n';
  assert.strictEqual(run(input, ['-d']).stdout, 'a\nc\n');
});

test('-d ignores non-adjacent duplicates', () => {
  const input = 'a\nb\na\nb\n';
  assert.strictEqual(run(input, ['-d']).stdout, '');
});

test('-u prints only unique lines', () => {
  const input = 'a\na\nb\nc\nc\nd\n';
  assert.strictEqual(run(input, ['-u']).stdout, 'b\nd\n');
});

test('-d and -u together exits with code 2', () => {
  const res = run('a\n', ['-d', '-u']);
  assert.strictEqual(res.status, 2);
  assert.strictEqual(res.stdout, '');
  assert.ok(res.stderr.length > 0);
});

test('order of -d -u flags does not matter for the error', () => {
  const res = run('a\n', ['-u', '-d']);
  assert.strictEqual(res.status, 2);
});

test('empty input produces empty output', () => {
  assert.strictEqual(run('', ['-c']).stdout, '');
  assert.strictEqual(run('', ['-d']).status, 0);
  assert.strictEqual(run('', ['-u']).stdout, '');
});

test('input without trailing newline still processed', () => {
  assert.strictEqual(run('a\nb\nb'), 'placeholder');
});

test('-c -d combined shows counts of duplicated lines only', () => {
  const input = 'a\na\nb\nc\nc\n';
  assert.strictEqual(
    run(input, ['-c', '-d']).stdout,
    '      2 a\n      2 c\n'
  );
});

